        CultEvent.Conditional("mv02", c => c[StatId.Reputation].Value <= 150, new Question("대홍수가 마을을 덮쳤을 때, 연회장에 숨은 명사들 대신 당신의 신도들만 진흙탕에서 사람들을 꺼냈습니다.\u001FWhen a great flood hit the town, only your followers waded into the mud to pull people out, while the celebrities hid in banquet halls.",
