        CultEvent.Conditional("mv07", c => c[StatId.Reputation].Value <= 300, new Question("탐욕 경연 대회 우승자가 파산한 뒤, 신문 칼럼이 \"그 인내의 교단이 옳았던 건 아닐까\"라고 묻습니다.\u001FAfter the champion of the Greed Contest goes bankrupt, a newspaper column asks, \"Was that cult of patience right all along?\"",
