                new Choice("인내에 대한 공개 강연을 엽니다\u001FHold a public lecture on patience", 0.75f, new Outcome("청중이 끝까지 자리를 지킵니다.\u001FThe audience stays to the very end.").C(StatId.Reputation, 12).C(StatId.Doctrine, 3),
