        CultEvent.Conditional("mv08", c => c[StatId.Reputation].Value <= 300, new Question("당신에게서 \"정직\"을 배운 전 신도가 법정에서 거짓 증언을 거부해 무고한 이를 구했다는 소식이 들립니다.\u001FWord arrives that a former follower who learned honesty from you refused to give false testimony in court and saved an innocent person.",
