                    new Outcome("몸이 먼저 무너져 사흘을 앓아눕습니다.\u001FYour body gives out first and you're bedridden for three days.").P(PersonalStatId.Health, -8).P(PersonalStatId.Mentality, -5)).With(PersonalStatId.Piety))),
        CultEvent.Conditional("mh02", c => c[StatId.FollowerFaith].Value <= 80, new Question("신도들이 연회장에 와도 웃지 않습니다. 술잔을 든 손이 기계적으로 움직일 뿐입니다.\u001FYour followers come to the feasts but no longer laugh. Their hands lift their cups mechanically.",
                new Choice("온천 휴양지로 단체 여행을 보냅니다\u001FSend them on a group hot-spring retreat", new Outcome("돌아온 신도들의 볼에 혈색이 돕니다.\u001FYour followers return with color in their cheeks.").C(StatId.FollowerFaith, 10).P(PersonalStatId.Health, 5).C(StatId.Offerings, -20).P(PersonalStatId.Appetite, 1)),
                new Choice("연회를 멈추고 금식일을 선포합니다\u001FHalt the feasts and declare a fast day", new Outcome("신도들은 어리둥절하지만 묘하게 개운해합니다.\u001FYour followers are puzzled but oddly refreshed.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Temperance, 3).C(StatId.Reputation, -6)))),
        CultEvent.Conditional("mh03", c => c[StatId.LeaderFaith].Value <= 80, new Question("유명 미식가 후원자가 \"지친 교주님을 위한 백 접시 코스\"를 대접하겠다고 제안합니다.\u001FA famous gourmet patron offers to serve \"a hundred-course meal for the weary leader.\"",
