                new Choice("후원자에게 답례 연회를 크게 엽니다\u001FThrow a lavish return banquet for the patron", 0.80f, new Outcome("후원자가 감동해 다음 후원을 약속합니다.\u001FMoved, the patron promises further support.").C(StatId.LeaderFaith, 5).C(StatId.Reputation, 6).C(StatId.Offerings, -15),
