        CultEvent.Conditional("mh04", c => c[StatId.LeaderFaith].Value <= 80 && c[StatId.FollowerFaith].Value <= 80, new Question("교단 전체가 무기력에 빠졌습니다. 떠돌이 치유사가 \"쾌락의 균형\"을 되찾아 주겠다며 문을 두드립니다.\u001FThe whole cult has sunk into lethargy. A wandering healer knocks, promising to restore \"the balance of pleasure.\"",
