        CultEvent.Conditional("mh05", c => c[StatId.FollowerFaith].Value <= 80, new Question("쾌락 경쟁에 지친 신도 몇이 \"이젠 아무것도 즐겁지 않다\"며 교단을 떠나려 합니다.\u001FA few followers, worn out by the race for pleasure, want to leave, saying \"Nothing is fun anymore.\"",
                new Choice("개인 휴양 별장을 내어 줍니다\u001FOffer them a private retreat villa", new Outcome("별장에서 쉬던 신도들이 편지를 보내옵니다.\u001FThe followers resting at the villa send letters of thanks.").C(StatId.FollowerFaith, 9).C(StatId.Offerings, -15).P(PersonalStatId.Greed, -1)),
