        CultEvent.Conditional("mh06", c => c[StatId.LeaderFaith].Value <= 80, new Question("부유한 후원자가 남쪽 섬의 비밀 휴양지를 한 달간 빌려 주겠다고 합니다.\u001FA wealthy patron offers you a secret island resort in the south for a month.",
                new Choice("한 달 내내 늘어지게 쉽니다\u001FLounge lazily the entire month", new Outcome("돌아오니 몸은 가볍지만 측근들이 자리를 넘보고 있습니다.\u001FYou return refreshed, but your aides have been eyeing your seat.").P(PersonalStatId.Health, 12).P(PersonalStatId.Mentality, 8).C(StatId.Authority, -5)),
