        CultEvent.Conditional("mh07", c => c[StatId.LeaderFaith].Value <= 80 && c[StatId.FollowerFaith].Value <= 80, new Question("교단 축제를 앞두고 아무도 준비할 기운이 없습니다. 유명 축제 기획사가 \"대신 다 해 드리죠\"라며 견적서를 내밉니다.\u001FAhead of the cult festival, no one has the energy to prepare. A famous event agency hands you a quote, saying \"We'll do it all for you.\"",
                new Choice("돈을 내고 편히 즐깁니다\u001FPay up and enjoy it with ease", new Outcome("오랜만에 모두가 손님처럼 축제를 즐깁니다.\u001FFor once, everyone enjoys the festival like guests.").C(StatId.LeaderFaith, 7).C(StatId.FollowerFaith, 7).C(StatId.Offerings, -25).P(PersonalStatId.Lust, 1)),
