        CultEvent.Conditional("mh10", c => c[StatId.LeaderFaith].Value <= 80, new Question("쾌락에 무뎌진 당신 앞에 예언자를 자처하는 노파가 나타나 \"욕망은 쉬어야 다시 자란다\"고 속삭입니다.\u001FWith your senses dulled by pleasure, an old woman claiming to be a prophet appears and whispers, \"Desire must rest to grow again.\"",
