        CultEvent.Conditional("ms001", c => c[StatId.Followers].Value >= 50 && c[StatId.Reputation].Value >= 600, new Question("시장 상인 조합이 당신의 교단을 \"성공의 학교\"로 추천하고 싶다며 찾아옵니다.\u001FThe market guild visits, wanting to endorse your cult as a \"school of success.\"",
