                new Choice("작품을 심사해 골라 받습니다\u001FJudge their work and choose", 0.75f, new Outcome("엄선된 예술가들이 교단의 품격을 높였습니다.\u001FThe select few raised the cult's prestige.").C(StatId.Doctrine, 4).C(StatId.Reputation, 5),
                    new Outcome("떨어진 자들이 교단을 비방하는 노래를 퍼뜨렸습니다.\u001FThe rejected spread songs mocking the cult.").C(StatId.Reputation, -5)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_greed10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10a")) > 0, new Question("황금 교단의 곳간이 넘쳐 금화가 복도에 쌓일 지경입니다. 도둑들이 신전 주위를 맴돕니다.\u001FThe Golden Cult's vaults overflow until coins pile in the corridors. Thieves circle the temple.",
                new Choice("금으로 신전 지붕을 덮습니다\u001FGild the temple roof with gold", 0.70f, new Outcome("황금 지붕은 멀리서도 보이는 자랑이 되었습니다.\u001FThe golden roof became a boast seen from afar.").C(StatId.Reputation, 8).P(PersonalStatId.Greed, 2).C(StatId.Offerings, -6),
                    new Outcome("밤사이 지붕 금박이 통째로 뜯겨 나갔습니다.\u001FOvernight the gold leaf was stripped clean.").C(StatId.Offerings, -12)).With(PersonalStatId.Greed),
                new Choice("용병을 고용해 곳간을 지킵니다\u001FHire mercenaries to guard the vaults", new Outcome("곳간 앞에 창이 번뜩이자 도둑들이 사라졌습니다.\u001FWith spears gleaming at the vaults, the thieves vanished.").C(StatId.Authority, 4).C(StatId.Offerings, -4)))),
        CultEvent.Conditional("mf_greed10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10a")) > 0, new Question("상인 길드가 교단의 금을 빌려 대규모 무역선을 띄우자고 제안합니다. 이자는 두 배입니다.\u001FThe merchant guild proposes borrowing the cult's gold to launch a great trade fleet, at double interest.",
                new Choice("빌려 줍니다\u001FLend the gold", 0.55f, new Outcome("배들이 돌아오자 금은 두 배가 되었습니다.\u001FThe ships returned and the gold doubled.").C(StatId.Offerings, 15).P(PersonalStatId.Greed, 2),
                    new Outcome("폭풍에 선단이 가라앉았습니다.\u001FA storm sank the fleet.").C(StatId.Offerings, -12).P(PersonalStatId.Wealth, -4)).With(PersonalStatId.Greed),
                new Choice("거절하고 금을 쌓아 둡니다\u001FRefuse and hoard the gold", new Outcome("길드는 당신을 겁쟁이 수전노라 불렀습니다.\u001FThe guild called you a cowardly miser.").C(StatId.Offerings, 4).P(PersonalStatId.Greed, 1).C(StatId.Reputation, -2)))),
        CultEvent.Conditional("mf_greed10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10a")) > 0, new Question("가난한 신도들이 헌금 액수에 따라 자리가 나뉘는 의식에 불만을 터뜨립니다.\u001FPoor followers protest the rites where seating is ranked by how much one offers.",
                new Choice("헌금 순위를 더 공개적으로 만듭니다\u001FMake the offering ranks even more public", 0.65f, new Outcome("부자들이 앞자리를 다투며 헌금을 더 냈습니다.\u001FThe rich fought for front seats and gave more.").C(StatId.Offerings, 10).P(PersonalStatId.Greed, 2),
                    new Outcome("가난한 신도들이 적잖이 떠났습니다.\u001FQuite a few poor followers left.").C(StatId.Followers, -6).C(StatId.FollowerFaith, -4)).With(PersonalStatId.Greed),
                new Choice("하루만 자리를 자유롭게 합니다\u001FFree the seating for one day", new Outcome("가난한 이들은 처음으로 앞자리에서 기도했습니다.\u001FFor once the poor prayed in the front rows.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Charity, 1).C(StatId.Offerings, -3)))),
        CultEvent.Conditional("mf_greed10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10a")) > 0, new Question("왕실 재무관이 교단 금고에 세금을 매기겠다며 장부를 들고 찾아왔습니다.\u001FThe royal treasurer arrives with ledgers, intent on taxing the cult's vaults.",
                new Choice("재무관에게 금을 쥐여 줍니다\u001FPress gold into the treasurer's hand", 0.60f, new Outcome("장부의 숫자가 마법처럼 줄어들었습니다.\u001FThe figures in the ledger shrank as if by magic.").C(StatId.Authority, 5).P(PersonalStatId.Greed, 1).C(StatId.Offerings, -4),
                    new Outcome("뇌물이 들통나 세금이 더 무겁게 매겨졌습니다.\u001FThe bribe was exposed and the tax was raised.").C(StatId.Reputation, -8).C(StatId.Offerings, -8)).With(PersonalStatId.Greed),
                new Choice("장부를 숨기고 버팁니다\u001FHide the books and hold out", 0.50f, new Outcome("재무관은 빈손으로 돌아갔습니다.\u001FThe treasurer left empty-handed.").C(StatId.Offerings, 6).P(PersonalStatId.Ambition, 1),
                    new Outcome("병사들이 들이닥쳐 금고를 뒤졌습니다.\u001FSoldiers stormed in and searched the vaults.").C(StatId.Authority, -6).C(StatId.Offerings, -10)).With(PersonalStatId.Greed),
                new Choice("세금을 순순히 냅니다\u001FPay the tax willingly", new Outcome("사람들은 황금 교단이 순진하다며 웃었습니다.\u001FPeople laughed that the Golden Cult was naive.").C(StatId.Offerings, -8).P(PersonalStatId.Integrity, 2).P(PersonalStatId.Piety, 2).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_greed10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10a")) > 0, new Question("금을 숭배하는 경쟁 종파 '은빛 손'이 당신 신도들에게 더 높은 배당을 약속하며 빼돌리고 있습니다.\u001FA rival gold-worshipping sect, the 'Silver Hand', lures your followers away with promises of higher dividends.",
                new Choice("더 큰 배당을 약속합니다\u001FPromise bigger dividends", 0.60f, new Outcome("신도들이 돌아와 당신의 금을 찬양했습니다.\u001FFollowers returned to praise your gold.").C(StatId.Followers, 6).P(PersonalStatId.Greed, 2).C(StatId.Offerings, -6),
                    new Outcome("약속을 지키기 어려워 금고가 휘청였습니다.\u001FThe promise strained the vaults.").C(StatId.Offerings, -10).C(StatId.FollowerFaith, -3)).With(PersonalStatId.Greed),
                new Choice("은빛 손을 통째로 사들입니다\u001FBuy out the Silver Hand outright", 0.45f, new Outcome("경쟁 종파의 간판이 황금으로 바뀌었습니다.\u001FThe rival's banner was replaced with gold.").C(StatId.Followers, 10).C(StatId.Authority, 5).C(StatId.Offerings, -10),
                    new Outcome("그들은 금만 챙기고 달아났습니다.\u001FThey took the gold and fled.").C(StatId.Offerings, -12)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_greed10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10b")) > 0, new Question("영리한 상회가 연 번영의 신전 시장에 상인들이 몰려듭니다. 그런데 한 상인이 저울을 교묘히 조작해 상회의 몫을 몰래 떼어 온 것이 드러났습니다.\u001FMerchants flock to the Temple of Prosperity's market, run by the shrewd trading house. But one merchant has been cleverly rigging his scales to skim the house's cut.",
                new Choice("본보기로 쫓아냅니다\u001FThrow him out as an example", new Outcome("상회의 몫을 떼먹으면 끝장이라는 소문이 시장에 돌았습니다.\u001FWord spread through the market: skim the house and you are finished.").C(StatId.Authority, 5).C(StatId.Reputation, 3).C(StatId.Offerings, -3)),
                new Choice("그의 수법을 상회에 들입니다\u001FBring his trick into the trading house", 0.70f, new Outcome("그의 교묘한 수법이 상회의 새로운 이윤이 되었습니다.\u001FHis clever trick became a new source of profit for the house.").C(StatId.Offerings, 8).P(PersonalStatId.Greed, 2),
                    new Outcome("그는 상회 장부까지 속이고 달아났습니다.\u001FHe cooked the house's books as well and fled.").C(StatId.Offerings, -5).C(StatId.Reputation, -3)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_greed10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10b")) > 0, new Question("신전이 운영하는 은행에 예금하려는 사람들의 줄이 끝없이 이어집니다. 금고 담당자는 이자를 올리자고 합니다.\u001FAn endless line forms to deposit at the temple's bank. The vault keeper suggests raising interest rates.",
                new Choice("이자를 올려 더 끌어모읍니다\u001FRaise rates to draw more in", 0.65f, new Outcome("신전 은행은 왕국 제일의 금고가 되었습니다.\u001FThe temple bank became the realm's greatest vault.").C(StatId.Offerings, 12).P(PersonalStatId.Wealth, 4).P(PersonalStatId.Greed, 1),
                    new Outcome("인출 소동이 벌어져 금고가 크게 흔들렸습니다.\u001FA bank run shook the vaults badly.").C(StatId.Offerings, -10).C(StatId.Reputation, -5)).With(PersonalStatId.Greed),
                new Choice("지금 이자를 유지합니다\u001FKeep the current rate", new Outcome("더 높은 이자를 찾아 떠난 예금자도 있었지만 금고는 안전했습니다.\u001FSome depositors left for higher rates, but the vault stayed safe.").C(StatId.Offerings, 4).P(PersonalStatId.Patience, 1).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_greed10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10b")) > 0, new Question("투자 재단에서 돈 버는 법을 배운 신도 하나가 큰 부자가 되어 신전에 황금 제단을 바치겠다고 합니다. 그는 대신 장로 자리를 원합니다.\u001FA follower who learned to make money at the investment fund has grown rich and offers the temple a golden altar, asking for an elder's seat in return.",
                new Choice("장로 자리를 줍니다\u001FGrant him the seat", 0.70f, new Outcome("황금 제단이 신전을 눈부시게 밝혔습니다.\u001FThe golden altar lit the temple dazzlingly.").C(StatId.Offerings, 12).C(StatId.Authority, -2).P(PersonalStatId.Greed, 1),
                    new Outcome("그는 장로가 되자 교리에 장사를 섞었습니다.\u001FAs elder he mixed commerce into doctrine.").C(StatId.Doctrine, -5)).With(PersonalStatId.Greed),
                new Choice("제단만 감사히 받습니다\u001FAccept only the altar with thanks", 0.50f, new Outcome("그는 서운했지만 제단을 바쳤습니다.\u001FDisappointed, he still gave the altar.").C(StatId.Offerings, 8).C(StatId.Reputation, 3),
                    new Outcome("그는 화를 내며 제단을 도로 가져갔습니다.\u001FHe angrily took the altar back.").C(StatId.Offerings, -3).C(StatId.Followers, -2)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_greed10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10b")) > 0, new Question("흉년이 들자 사람들은 번영의 신전이 곡식값을 올려 돈을 벌 거라 기대합니다.\u001FIn a lean year, people expect the Temple of Prosperity to profit by raising grain prices.",
                new Choice("값을 올려 크게 법니다\u001FRaise prices and profit hugely", 0.75f, new Outcome("세상은 당신의 수완을 칭송했습니다.\u001FThe world praised your business acumen.").C(StatId.Offerings, 14).P(PersonalStatId.Wealth, 5).P(PersonalStatId.Greed, 2),
                    new Outcome("굶주린 군중이 곡물 창고를 습격했습니다.\u001FStarving crowds raided the granary.").C(StatId.Followers, -6).C(StatId.Reputation, -4)).With(PersonalStatId.Greed),
                new Choice("적정 가격에 풉니다\u001FSell at a fair price", new Outcome("상인들은 비웃었지만 서민들은 당신을 축복했습니다.\u001FMerchants sneered, but common folk blessed you.").C(StatId.FollowerFaith, 5).P(PersonalStatId.Integrity, 1).C(StatId.LeaderFaith, 2).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_greed10b_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("greed10b")) > 0, new Question("이웃 왕국의 사절이 쌓아 올린 부의 비결을 배우겠다며 투자 재단에 유학생들을 보내겠다고 합니다.\u001FAn envoy from a neighboring kingdom wants to send students to the investment fund to learn the secret of the temple's amassed wealth.",
                new Choice("비싼 수업료를 받고 가르칩니다\u001FTeach them for a hefty fee", 0.80f, new Outcome("유학생들이 고국에 당신의 이름을 퍼뜨렸습니다.\u001FThe students spread your name back home.").C(StatId.Offerings, 10).C(StatId.Reputation, 5),
                    new Outcome("그들은 비결만 훔쳐 경쟁 신전을 세웠습니다.\u001FThey stole the secrets and built a rival temple.").C(StatId.Reputation, -3)).With(PersonalStatId.Greed),
                new Choice("무료로 가르칩니다\u001FTeach them for free", new Outcome("세상은 비결을 공짜로 넘긴 신전을 비웃었지만, 유학생들은 깊이 감사했습니다.\u001FThe world mocked the temple for giving its secrets away, but the students were deeply grateful.").P(PersonalStatId.Charity, 2).P(PersonalStatId.Piety, 2).C(StatId.Offerings, -4).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_appetite10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10a")) > 0, new Question("풍요의 왕국에서 백일 잔치가 열립니다. 남은 음식이 강처럼 버려지자 굶주린 이웃 마을 사람들이 몰려옵니다.\u001FA hundred-day feast is held in the Kingdom of Plenty. As leftovers are dumped like a river, starving villagers from nearby swarm in.",
                new Choice("그들도 식탁에 앉힙니다\u001FSeat them at the table too", new Outcome("새 얼굴들이 배를 채우고 신도가 되었습니다.\u001FThe newcomers ate their fill and joined the cult.").C(StatId.Followers, 6).C(StatId.Offerings, -5).P(PersonalStatId.Appetite, 1)),
                new Choice("잔치는 신도만의 것이라 돌려보냅니다\u001FTurn them away; the feast is for followers", 0.80f, new Outcome("신도들은 자신들이 선택받았다며 뿌듯해했습니다.\u001FFollowers felt proud to be the chosen few.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Appetite, 2),
                    new Outcome("돌아선 이들이 교단을 저주했습니다.\u001FThose turned away cursed the cult.").C(StatId.Reputation, -6)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_appetite10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10a")) > 0, new Question("교단 요리장이 전설의 '백 가지 요리 대연회'를 준비하겠다고 합니다. 재료비가 어마어마합니다.\u001FThe cult's head chef proposes the legendary 'Hundred Dish Banquet'. The ingredient cost is staggering.",
                new Choice("아낌없이 허락합니다\u001FApprove without restraint", 0.65f, new Outcome("대연회는 왕국 역사에 남을 축제가 되었습니다.\u001FThe banquet became a festival for the history books.").C(StatId.Reputation, 10).C(StatId.FollowerFaith, 5).P(PersonalStatId.Appetite, 2).C(StatId.Offerings, -10),
                    new Outcome("식중독이 돌아 잔치가 아수라장이 되었습니다.\u001FFood poisoning turned the feast into chaos.").C(StatId.Offerings, -12).P(PersonalStatId.Health, -1)).With(PersonalStatId.Greed),
                new Choice("반만 준비하게 합니다\u001FHave him prepare half", new Outcome("작지만 맛있는 잔치였습니다.\u001FA smaller but delicious feast.").C(StatId.FollowerFaith, 3).C(StatId.Offerings, -4)))),
        CultEvent.Conditional("mf_appetite10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10a")) > 0, new Question("신도들이 너무 살쪄서 노동과 순례를 못 하겠다는 불평이 나옵니다. 그들은 그래도 더 먹고 싶어 합니다.\u001FFollowers have grown so fat they complain they cannot work or make pilgrimages, yet they still want more food.",
                new Choice("더 먹게 합니다, 그것이 축복입니다\u001FLet them eat more; it is a blessing", new Outcome("신도들은 행복했지만 몇은 병들었습니다.\u001FThey were happy, though some fell ill.").C(StatId.FollowerFaith, 5).P(PersonalStatId.Appetite, 2).C(StatId.Followers, -2)),
                new Choice("식후 춤 의식을 만듭니다\u001FCreate a post-meal dance rite", 0.70f, new Outcome("배부른 춤이 교단의 새 전통이 되었습니다.\u001FThe full-bellied dance became a new tradition.").P(PersonalStatId.Health, 4).C(StatId.Communion, 4),
                    new Outcome("신도들은 먹는 시간이 줄었다며 투덜댔습니다.\u001FFollowers grumbled that eating time was cut.").C(StatId.FollowerFaith, -3)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_appetite10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10a")) > 0, new Question("풍요의 왕국 곡창을 노린 산적 떼가 국경에 모였습니다. 그들도 배고픈 자들입니다.\u001FA bandit horde eyeing the Kingdom of Plenty's granaries gathers at the border. They too are hungry.",
                new Choice("음식으로 그들을 매수합니다\u001FBuy them off with food", 0.70f, new Outcome("산적들은 배를 채우고 교단의 문지기가 되었습니다.\u001FFed, the bandits became the cult's gatekeepers.").C(StatId.Followers, 5).C(StatId.Offerings, -6),
                    new Outcome("그들은 받은 뒤 더 많이 요구했습니다.\u001FThey took it and demanded more.").C(StatId.Offerings, -10)).With(PersonalStatId.Greed),
                new Choice("무장한 신도로 쫓아냅니다\u001FDrive them off with armed followers", 0.55f, new Outcome("산적들은 꽁무니를 뺐습니다.\u001FThe bandits fled.").C(StatId.Authority, 7).P(PersonalStatId.Ambition, 1),
                    new Outcome("싸움에서 신도들이 다쳤습니다.\u001FFollowers were hurt in the fight.").C(StatId.Followers, -5).P(PersonalStatId.Health, -2)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_appetite10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10a")) > 0, new Question("미식가 비평가가 풍요의 왕국 음식은 양만 많고 맛이 없다는 글을 퍼뜨렸습니다.\u001FA gourmet critic spreads a review saying the Kingdom of Plenty's food is all quantity and no taste.",
                new Choice("그를 초대해 최고의 만찬을 대접합니다\u001FInvite him to a supreme dinner", 0.60f, new Outcome("그는 다음 글에서 당신의 식탁을 극찬했습니다.\u001FHis next review raved about your table.").C(StatId.Reputation, 8).P(PersonalStatId.Appetite, 1),
                    new Outcome("그는 더 신랄한 평을 썼습니다.\u001FHe wrote an even harsher review.").C(StatId.Reputation, -5).C(StatId.Offerings, -5)).With(PersonalStatId.Greed),
                new Choice("비웃고 넘깁니다\u001FLaugh it off", new Outcome("신도들은 맛보다 배부름이 낫다며 웃었습니다.\u001FFollowers laughed that fullness beats flavor.").C(StatId.FollowerFaith, 2).P(PersonalStatId.Patience, 1)))),
        CultEvent.Conditional("mf_appetite10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10b")) > 0, new Question("대지의 어머니가 된 당신에게 기근 지역 세 곳이 동시에 구호를 청합니다. 곡식은 한 곳 몫뿐입니다.\u001FYou are Mother Earth now, and three famine regions beg you for relief at once. You have grain for only one.",
                new Choice("가장 큰 도시로 보냅니다\u001FSend it to the largest city", new Outcome("큰 도시가 당신을 어머니라 부르기 시작했습니다.\u001FThe great city began to call you mother.").C(StatId.Followers, 8).C(StatId.Reputation, 3)),
                new Choice("셋으로 나눠 보냅니다\u001FSplit it three ways", 0.60f, new Outcome("부족했지만 세 곳 모두 고비를 넘겼습니다.\u001FIt was not enough, yet all three survived.").C(StatId.Reputation, 5).C(StatId.FollowerFaith, 4).P(PersonalStatId.Charity, 1),
                    new Outcome("너무 적게 나눠 아무 데도 구하지 못했습니다.\u001FSpread so thin, it saved no one.").C(StatId.Followers, -4).C(StatId.Reputation, -1)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_appetite10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10b")) > 0, new Question("굶주린 이들이 신전에 몰려와 살게 되면서 원래 신도들이 자기 몫이 줄었다고 불평합니다.\u001FThe hungry have moved into the temple, and longtime followers complain their share has shrunk.",
                new Choice("원래 신도에게 더 큰 몫을 줍니다\u001FGive longtime followers a bigger share", new Outcome("신도들은 만족했지만 새 이들은 서운해했습니다.\u001FFollowers were satisfied; newcomers felt slighted.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Appetite, 1).C(StatId.Reputation, -2)),
                new Choice("새 밭을 일궈 모두의 몫을 늘립니다\u001FClear new fields to grow everyone's share", 0.65f, new Outcome("함께 일한 밭에서 풍성한 수확이 났습니다.\u001FThe shared fields gave a rich harvest.").C(StatId.Offerings, 6).C(StatId.Communion, 5).P(PersonalStatId.Patience, 1),
                    new Outcome("가뭄에 새 밭은 말라 버렸습니다.\u001FDrought withered the new fields.").P(PersonalStatId.Health, -4).C(StatId.Offerings, -4)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_appetite10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10b")) > 0, new Question("곡물 상인 연합이 대지의 어머니 때문에 장사가 망했다며 신전의 무료 급식을 막으려 합니다.\u001FA grain merchants' union, claiming Mother Earth ruined their trade, moves to stop the temple's free meals.",
                new Choice("상인들에게 급식 납품을 맡깁니다\u001FContract the merchants to supply the meals", 0.75f, new Outcome("상인들은 적에서 동업자가 되었습니다.\u001FThe merchants turned from foes to partners.").C(StatId.Offerings, -5).C(StatId.Authority, 4).P(PersonalStatId.Greed, 1),
                    new Outcome("그들은 납품가를 터무니없이 올렸습니다.\u001FThey jacked up the supply prices absurdly.").C(StatId.Offerings, -10)).With(PersonalStatId.Greed),
                new Choice("군중을 모아 상인들에게 맞섭니다\u001FRally the crowd against the merchants", 0.55f, new Outcome("배고픈 군중의 함성에 상인들이 물러섰습니다.\u001FThe roar of the hungry crowd made them back off.").C(StatId.Reputation, 7).C(StatId.Followers, 5),
                    new Outcome("폭동으로 번져 신전이 비난받았습니다.\u001FIt turned into a riot and the temple was blamed.").C(StatId.Authority, -5).C(StatId.Reputation, -4)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_appetite10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10b")) > 0, new Question("한 어머니가 아이를 살려 준 대가로 집안 대대로 신전에 땅을 바치겠다고 합니다.\u001FA mother whose child you saved offers to deed her family's land to the temple for generations.",
                new Choice("감사히 받습니다\u001FAccept with gratitude", new Outcome("새 땅에서 곡식이 자라기 시작했습니다.\u001FGrain began to grow on the new land.").C(StatId.Offerings, 8).P(PersonalStatId.Wealth, 3).P(PersonalStatId.Greed, 1)),
                new Choice("땅은 돌려주고 신도로 맞습니다\u001FReturn the land and welcome her as a follower", new Outcome("세상은 땅을 돌려준 신전을 어리석다 했지만, 그녀의 이야기는 신도들 사이에 퍼졌습니다.\u001FThe world called returning the land foolish, but her story spread among your followers.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Charity, 2).P(PersonalStatId.Piety, 2).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_appetite10b_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("appetite10b")) > 0, new Question("대지의 어머니를 섬기는 축제에서 신도들이 당신에게 첫 수확물을 먹여 주는 의식을 하려 합니다. 양이 엄청납니다.\u001FAt the Mother Earth festival, followers wish to hand-feed you the first harvest. The amount is enormous.",
                new Choice("모두 받아먹습니다\u001FEat every bite", 0.60f, new Outcome("신도들은 어머니가 대지를 품었다며 환호했습니다.\u001FFollowers cheered that Mother had embraced the earth.").C(StatId.FollowerFaith, 8).P(PersonalStatId.Appetite, 3),
                    new Outcome("결국 당신은 탈이 나 앓아누웠습니다.\u001FYou ended up sick in bed.").P(PersonalStatId.Health, -2)).With(PersonalStatId.Greed),
                new Choice("한 입씩만 먹고 나눠 줍니다\u001FTake a bite each and share the rest", new Outcome("남은 음식은 모두의 잔치가 되었습니다.\u001FThe rest became a feast for all.").C(StatId.Communion, 5).P(PersonalStatId.Temperance, 1).C(StatId.FollowerFaith, 2)))),
        CultEvent.Conditional("mf_ambition10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10a")) > 0, new Question("지상의 왕좌에 오른 당신을 위해 신도들이 대관식을 준비합니다. 옛 왕은 아직 살아 있습니다.\u001FFollowers prepare a coronation for you upon the Earthly Throne. The old king still lives.",
                new Choice("성대한 대관식을 엽니다\u001FHold a grand coronation", 0.55f, new Outcome("만인이 당신 앞에 무릎을 꿇었습니다.\u001FAll bowed before you.").C(StatId.Authority, 12).P(PersonalStatId.Ambition, 3).C(StatId.Reputation, 4),
                    new Outcome("옛 왕의 지지자들이 대관식장에서 난동을 부렸습니다.\u001FThe old king's loyalists rioted at the ceremony.").C(StatId.Authority, -6).C(StatId.Reputation, -6)).With(PersonalStatId.Greed),
                new Choice("옛 왕을 명예 고문으로 앉힙니다\u001FMake the old king an honorary advisor", 0.80f, new Outcome("옛 왕의 지지자들도 당신을 따르게 되었습니다.\u001FEven the old king's loyalists came to follow you.").C(StatId.Authority, 6).C(StatId.Reputation, 5),
                    new Outcome("그는 뒤에서 음모를 꾸미기 시작했습니다.\u001FHe began plotting behind your back.").C(StatId.Authority, -4)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_ambition10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10a")) > 0, new Question("당신의 장군이 이웃 영지를 정복하고 돌아와 그 땅의 영주 자리를 요구합니다.\u001FYour general returns from conquering a neighboring domain and demands its lordship.",
                new Choice("영지를 하사합니다\u001FGrant him the domain", new Outcome("충성스러운 영주가 생겼습니다.\u001FYou gained a loyal lord.").C(StatId.Authority, 5).C(StatId.Followers, 5)),
                new Choice("당신이 직접 다스립니다\u001FRule it yourself", 0.60f, new Outcome("왕국의 영토가 당신 손에 모였습니다.\u001FThe realm's lands gathered in your hands.").C(StatId.Authority, 10).P(PersonalStatId.Ambition, 2),
                    new Outcome("분노한 장군이 병사를 이끌고 이탈했습니다.\u001FThe furious general deserted with his troops.").C(StatId.Authority, -8).C(StatId.Followers, -4)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_ambition10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10a")) > 0, new Question("왕국이 커지자 지방마다 세금과 병역에 대한 불만이 터져 나옵니다.\u001FAs the kingdom grows, complaints about taxes and conscription erupt in every province.",
                new Choice("세금을 올려 군대를 늘립니다\u001FRaise taxes and expand the army", 0.65f, new Outcome("더 강해진 군대 앞에 불만이 잠잠해졌습니다.\u001FComplaints went silent before a stronger army.").C(StatId.Authority, 10).C(StatId.Offerings, 6).P(PersonalStatId.Ambition, 2),
                    new Outcome("반란이 일어나 지방 한 곳을 잃었습니다.\u001FA revolt cost you a province.").C(StatId.Followers, -8).C(StatId.Reputation, -5)).With(PersonalStatId.Greed),
                new Choice("한 해 세금을 면제합니다\u001FWaive taxes for a year", new Outcome("백성들은 왕을 칭송했지만 궁정은 불안해했습니다.\u001FThe people praised you, though the court grew uneasy.").C(StatId.FollowerFaith, 5).C(StatId.Offerings, -8).C(StatId.Reputation, 3)))),
        CultEvent.Conditional("mf_ambition10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10a")) > 0, new Question("이웃 세 나라가 당신의 왕국을 견제하려 동맹을 맺었다는 소식이 들립니다.\u001FNews comes that three neighboring nations have allied to contain your kingdom.",
                new Choice("선제공격합니다\u001FStrike first", 0.45f, new Outcome("동맹은 무너졌고 당신의 이름이 대륙에 울렸습니다.\u001FThe alliance crumbled and your name rang across the continent.").C(StatId.Authority, 12).C(StatId.Followers, 6).P(PersonalStatId.Ambition, 3),
                    new Outcome("대패해 많은 신도를 잃었습니다.\u001FA crushing defeat cost many followers.").C(StatId.Followers, -10).P(PersonalStatId.Health, -2).C(StatId.Authority, -6)).With(PersonalStatId.Greed),
                new Choice("한 나라와 비밀 혼약을 맺어 동맹을 깹니다\u001FBreak the alliance with a secret marriage pact", 0.65f, new Outcome("동맹 하나가 당신 편으로 돌아섰습니다.\u001FOne ally turned to your side.").C(StatId.Authority, 7).P(PersonalStatId.Lust, 1),
                    new Outcome("밀약이 들통나 웃음거리가 되었습니다.\u001FThe pact leaked and you became a laughingstock.").C(StatId.Reputation, -5)).With(PersonalStatId.Greed),
                new Choice("국경 요새만 강화합니다\u001FOnly fortify the border", new Outcome("왕국은 버텼지만 사람들은 당신이 약해졌다고 했습니다.\u001FThe kingdom held, but people said you had softened.").C(StatId.Authority, 3).P(PersonalStatId.Patience, 1).C(StatId.Offerings, -5)))),
        CultEvent.Conditional("mf_ambition10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10a")) > 0, new Question("궁정의 젊은 신하가 왕좌를 노린다는 밀고가 들어왔습니다. 증거는 불확실합니다.\u001FAn informant reports that a young courtier covets the throne. The evidence is shaky.",
                new Choice("본보기로 숙청합니다\u001FPurge him as an example", new Outcome("궁정은 공포 속에 조용해졌습니다.\u001FThe court fell silent in fear.").C(StatId.Authority, 8).P(PersonalStatId.Ambition, 2).C(StatId.Reputation, -5)),
                new Choice("그를 더 높은 자리에 올려 감시합니다\u001FPromote him and keep watch", 0.60f, new Outcome("그는 감격해 충신이 되었습니다.\u001FOverwhelmed, he became a loyal servant.").C(StatId.Authority, 5).C(StatId.Doctrine, 3),
                    new Outcome("그는 그 자리를 발판 삼아 세력을 모았습니다.\u001FHe used the post to gather his own faction.").C(StatId.Authority, -8)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_ambition10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10b")) > 0, new Question("신정 국가가 된 지금, 교단의 율법을 나라의 법전에 새기는 회의가 열립니다. 법관들이 처벌 조항을 두고 갈립니다.\u001FNow a theocracy, a council meets to carve cult law into the national code. Judges split over the punishments.",
                new Choice("욕망을 거스르는 자를 벌하는 법을 넣습니다\u001FAdd a law punishing those who deny desire", 0.70f, new Outcome("법전은 욕망을 신성한 의무로 선언했습니다.\u001FThe code declared desire a sacred duty.").C(StatId.Doctrine, 8).C(StatId.Authority, 6).P(PersonalStatId.Ambition, 2),
                    new Outcome("가혹한 법에 백성들이 등을 돌렸습니다.\u001FThe harsh law turned the people away.").C(StatId.Reputation, -6)).With(PersonalStatId.Greed),
                new Choice("처벌 없이 권장만 합니다\u001FEncourage, without punishment", new Outcome("야심가들은 미지근한 법이라 비웃었지만 신도들은 안도했습니다.\u001FThe ambitious sneered at such a lukewarm law, but your followers were relieved.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Charity, 1).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_ambition10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10b")) > 0, new Question("국경 마을 하나가 신정에 반대해 옛 신을 다시 섬기고 있습니다.\u001FA border village opposes the theocracy and has returned to its old gods.",
                new Choice("사제단을 보내 개종시킵니다\u001FSend priests to convert them", 0.65f, new Outcome("마을은 다시 교단의 깃발을 올렸습니다.\u001FThe village raised the cult's banner again.").C(StatId.Followers, 6).C(StatId.Doctrine, 4),
                    new Outcome("사제들이 쫓겨나 망신을 당했습니다.\u001FThe priests were driven out in shame.").C(StatId.Reputation, -4).C(StatId.Followers, -2)).With(PersonalStatId.Greed),
                new Choice("마을에 자치를 허락합니다\u001FGrant the village autonomy", new Outcome("세상은 나약하다며 비웃었지만 마을은 조용해졌습니다.\u001FThe world laughed at your weakness, but the village grew quiet.").C(StatId.Authority, -4).P(PersonalStatId.Patience, 1).P(PersonalStatId.Charity, 1).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_ambition10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10b")) > 0, new Question("대사제 자리를 두고 당신의 두 제자가 권력 다툼을 벌입니다. 둘 다 유능합니다.\u001FTwo of your disciples battle for the seat of high priest. Both are capable.",
                new Choice("공개 토론으로 정합니다\u001FDecide by public debate", 0.75f, new Outcome("토론은 교리를 한층 날카롭게 다듬었습니다.\u001FThe debate sharpened the doctrine.").C(StatId.Doctrine, 6).C(StatId.Reputation, 4),
                    new Outcome("패자 쪽 파벌이 교단을 둘로 갈랐습니다.\u001FThe loser's faction split the cult.").C(StatId.Communion, -5)).With(PersonalStatId.Greed),
                new Choice("둘에게 권력을 나눠 줍니다\u001FDivide power between them", new Outcome("둘은 서로를 견제하며 일했습니다.\u001FThey worked while checking each other.").C(StatId.Authority, -3).C(StatId.Communion, 4)))),
        CultEvent.Conditional("mf_ambition10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10b")) > 0, new Question("이웃 왕이 신정 국가의 교리를 자기 나라 국교로 삼고 싶다며 당신을 초청합니다. 대신 그는 대사제 임명권을 원합니다.\u001FA neighboring king invites you, wishing to make your faith his state religion, but wants the right to appoint its high priest.",
                new Choice("조건을 받아들입니다\u001FAccept his terms", new Outcome("교단의 깃발이 이웃 나라에도 올랐습니다.\u001FThe cult's banner rose over another kingdom.").C(StatId.Followers, 10).C(StatId.Reputation, 5).C(StatId.Authority, -5)),
                new Choice("임명권은 넘기지 않겠다고 버팁니다\u001FRefuse to cede the appointment", 0.50f, new Outcome("왕은 결국 당신의 조건을 받아들였습니다.\u001FThe king eventually accepted your terms.").C(StatId.Followers, 8).C(StatId.Authority, 6).P(PersonalStatId.Ambition, 2),
                    new Outcome("왕은 모욕을 느끼고 초청을 거두었습니다.\u001FInsulted, the king withdrew his invitation.").C(StatId.Reputation, -4)).With(PersonalStatId.Greed))),
        CultEvent.Conditional("mf_ambition10b_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("ambition10b")) > 0, new Question("신정 아래 모든 재판이 신전에서 열리면서 사건이 산더미처럼 밀려 있습니다. 백성들이 판결을 기다리다 지쳐 갑니다.\u001FUnder the theocracy every trial is held in the temple, and cases have piled up. People grow weary waiting for verdicts.",
                new Choice("당신이 직접 하루 종일 판결합니다\u001FJudge cases yourself all day", 0.60f, new Outcome("당신의 빠른 판결이 칭송받았습니다.\u001FYour swift judgments were praised.").C(StatId.Authority, 6).C(StatId.Reputation, 6),
                    new Outcome("과로로 쓰러지고 오판 소문까지 돌았습니다.\u001FYou collapsed from overwork amid rumors of wrong verdicts.").P(PersonalStatId.Mentality, -6).P(PersonalStatId.Health, -3)).With(PersonalStatId.Greed),
                new Choice("하급 사제들에게 재판권을 나눕니다\u001FDelegate judgment to lower priests", new Outcome("재판은 빨라졌지만 당신의 손을 떠났습니다.\u001FTrials sped up but left your hands.").C(StatId.Doctrine, 3).C(StatId.Authority, -3)))),
        CultEvent.Conditional("mf_temperance10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10a")) > 0, new Question("시장 광장에서 상인들이 당신을 '아무것도 원하지 않는 바보'라 부르며 썩은 과일을 던집니다. 군중은 당신이 화를 내기를 기다립니다.\u001FIn the market square, merchants call you 'the fool who wants nothing' and pelt you with rotten fruit. The crowd waits for you to lose your temper.",
                new Choice("미소 지으며 과일을 주워 먹습니다\u001FSmile, pick up the fruit, and eat it", 0.70f, new Outcome("당신의 평온함에 군중이 머쓱해져 흩어집니다. 몇몇은 뒤를 돌아봅니다.\u001FYour calm leaves the crowd awkward, and they scatter. A few glance back.").P(PersonalStatId.Temperance, 3).C(StatId.LeaderFaith, 4).C(StatId.Reputation, -1),
                    new Outcome("웃음이 더 커지고, 당신은 오물 범벅으로 돌아옵니다.\u001FThe laughter only grows, and you return covered in filth.").C(StatId.Reputation, -3).P(PersonalStatId.Mentality, -2)).With(PersonalStatId.Integrity),
                new Choice("조용히 자리를 뜹니다\u001FQuietly walk away", new Outcome("아무 일도 없었던 듯 걸어가는 당신을 사람들이 김빠진 얼굴로 봅니다.\u001FPeople watch, deflated, as you walk off as if nothing happened.").C(StatId.Reputation, -2).P(PersonalStatId.Mentality, 2)))),
        CultEvent.Conditional("mf_temperance10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10a")) > 0, new Question("교단 금고가 도둑맞았습니다. 신도들은 공황에 빠졌지만, 당신은 잃은 것이 없다는 듯 평소처럼 명상합니다.\u001FThe cult treasury has been robbed. The followers panic, but you meditate as usual, as if nothing was lost.",
                new Choice("재물은 원래 짐이었다고 설법합니다\u001FPreach that wealth was always a burden", 0.65f, new Outcome("신도들이 당신의 흔들림 없는 얼굴에서 위안을 얻습니다.\u001FThe followers find comfort in your unshaken face.").C(StatId.FollowerFaith, 5).C(StatId.Offerings, -5).P(PersonalStatId.Temperance, 2),
                    new Outcome("\"그러니 가난하지\"라며 몇 명이 떠나갑니다.\u001F\"No wonder we're poor,\" some mutter, and leave.").C(StatId.Followers, -4).C(StatId.Offerings, -5)).With(PersonalStatId.Integrity),
                new Choice("도둑을 찾아 나섭니다\u001FGo after the thief", 0.50f, new Outcome("도둑을 붙잡아 금고 일부를 되찾습니다.\u001FYou catch the thief and recover part of the treasury.").C(StatId.Offerings, 6).C(StatId.Authority, 2),
                    new Outcome("헛걸음 끝에 넘어져 다치기만 합니다.\u001FAfter a wasted chase, you only manage to hurt yourself.").P(PersonalStatId.Health, -4).C(StatId.Offerings, -3)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_temperance10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10a")) > 0, new Question("유명한 쾌락주의 철학자가 공개 토론을 청해 '욕망 없는 삶은 죽음과 같다'고 당신을 몰아붙입니다.\u001FA famous hedonist philosopher challenges you to a public debate, insisting that 'a life without desire is death.'",
                new Choice("고요히 반박합니다\u001FCalmly rebut him", 0.55f, new Outcome("청중 대부분은 여전히 철학자 편이지만, 몇몇이 고개를 끄덕이고 철학자의 얼굴이 굳습니다.\u001FMost of the crowd still sides with him, but a few nod, and the philosopher's face stiffens.").C(StatId.Doctrine, 4).P(PersonalStatId.Temperance, 2).C(StatId.LeaderFaith, 3).C(StatId.Reputation, -1),
                    new Outcome("청중은 철학자의 화려한 말에 환호하고 당신을 야유합니다.\u001FThe audience cheers his flashy words and jeers at you.").C(StatId.Reputation, -3).P(PersonalStatId.Mentality, -2)).With(PersonalStatId.Integrity),
                new Choice("침묵으로 답합니다\u001FAnswer with silence", new Outcome("당신의 침묵을 사람들은 패배라 부르지만, 당신 마음은 고요합니다.\u001FPeople call your silence defeat, but your mind stays still.").C(StatId.LeaderFaith, 5).C(StatId.Reputation, -4)))),
        CultEvent.Conditional("mf_temperance10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10a")) > 0, new Question("역병이 돌아 측근 수행자가 숨졌습니다. 신도들은 당신이 무너질 것이라 수군댑니다.\u001FA plague has taken one of your closest disciples. The followers whisper that you will break.",
                new Choice("담담히 장례를 치릅니다\u001FHold the funeral with composure", new Outcome("흔들리지 않는 장례에 신도들이 서로를 붙잡고 버팁니다.\u001FYour steady funeral helps the followers hold on to one another.").C(StatId.FollowerFaith, 4).P(PersonalStatId.Mentality, 2).C(StatId.Communion, 3)),
                new Choice("홀로 눈물을 허락합니다\u001FAllow yourself to weep in private", 0.75f, new Outcome("슬픔을 흘려보낸 뒤 당신은 더 단단해집니다.\u001FHaving let the grief pass, you become firmer.").P(PersonalStatId.Mentality, 4).P(PersonalStatId.Piety, 2),
                    new Outcome("누군가 우는 모습을 보고 소문을 퍼뜨립니다.\u001FSomeone sees you crying and spreads rumors.").P(PersonalStatId.Mentality, -3).C(StatId.Authority, -2)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_temperance10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10a")) > 0, new Question("욕망 숭배의 축제날, 술에 취한 귀족이 당신을 무대로 끌어올려 '해탈자'를 조롱하는 연극에 세웁니다.\u001FOn a festival day of desire, a drunken noble drags you on stage to star in a play mocking 'the liberated one.'",
                new Choice("배역을 진지하게 연기합니다\u001FPlay the part with sincerity", 0.60f, new Outcome("조롱극이 묘하게 경건해지고, 관객 몇몇이 숙연해집니다.\u001FThe mockery turns strangely solemn, and some in the audience fall quiet.").C(StatId.LeaderFaith, 3).C(StatId.Followers, 3).P(PersonalStatId.Temperance, 1),
                    new Outcome("관객은 끝까지 웃고, 당신은 축제의 우스개가 됩니다.\u001FThey laugh to the end, and you become the festival's joke.").C(StatId.Reputation, -3)).With(PersonalStatId.Integrity),
                new Choice("정중히 무대에서 내려옵니다\u001FPolitely step down from the stage", new Outcome("귀족은 투덜대지만 당신을 붙잡지 못합니다.\u001FThe noble grumbles but cannot hold you.").C(StatId.Authority, 2).C(StatId.Reputation, -2)))),
        CultEvent.Conditional("mf_temperance10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10b")) > 0, new Question("방탕으로 몸을 망친 젊은 상인이 한밤중 사원 문을 두드리며 길을 묻습니다.\u001FA young merchant, ruined by excess, knocks on the temple door at midnight asking for a way out.",
                new Choice("밤새 그와 이야기합니다\u001FTalk with him through the night", 0.70f, new Outcome("새벽녘 그는 처음으로 맑은 눈을 하고 신도가 됩니다.\u001FBy dawn his eyes are clear for the first time, and he joins you.").C(StatId.Followers, 3).C(StatId.Doctrine, 3).P(PersonalStatId.Health, -2),
                    new Outcome("그는 다음 날 다시 술집으로 돌아가 당신을 비웃습니다.\u001FThe next day he returns to the tavern and mocks you.").P(PersonalStatId.Health, -3).C(StatId.Reputation, -2)).With(PersonalStatId.Integrity),
                new Choice("아침에 오라고 돌려보냅니다\u001FTell him to come back in the morning", new Outcome("당신은 푹 쉬었지만 그가 다시 올지는 알 수 없습니다.\u001FYou rest well, but whether he will return is unknown.").P(PersonalStatId.Health, 2).P(PersonalStatId.Mentality, 1)))),
        CultEvent.Conditional("mf_temperance10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10b")) > 0, new Question("신도들이 당신의 가르침을 필사하려 하지만, 영주는 '쓸모없는 금욕 서적'을 불태우라는 포고를 내립니다.\u001FFollowers want to copy your teachings, but the lord decrees that 'useless books of abstinence' be burned.",
                new Choice("몰래 필사를 계속합니다\u001FKeep copying in secret", 0.55f, new Outcome("등불 아래 쓴 사본들이 마을마다 은밀히 퍼집니다.\u001FCopies written by lamplight spread quietly from village to village.").C(StatId.Doctrine, 6).C(StatId.FollowerFaith, 3),
                    new Outcome("필사실이 발각되어 신도 몇이 끌려갑니다.\u001FThe scriptorium is discovered, and several followers are dragged away.").C(StatId.Authority, -5).C(StatId.Followers, -3)).With(PersonalStatId.Integrity),
                new Choice("가르침을 입으로만 전합니다\u001FPass the teachings on by word of mouth", new Outcome("책은 없어도 신도들은 서로의 기억을 맞춰 갑니다.\u001FWithout books, the followers piece together each other's memories.").C(StatId.Communion, 4).C(StatId.Doctrine, 1)))),
        CultEvent.Conditional("mf_temperance10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10b")) > 0, new Question("당신의 절식 수행을 흉내 내던 신도가 쓰러졌습니다. 마을 사람들은 '굶겨 죽이는 사교'라 손가락질합니다.\u001FA follower imitating your fasting collapses. The villagers point and call you 'a cult that starves people to death.'",
                new Choice("절제는 굶주림이 아니라고 바로잡습니다\u001FCorrect them: temperance is not starvation", new Outcome("당신은 직접 신도에게 죽을 먹이며 중용을 가르칩니다.\u001FYou feed the follower porridge yourself and teach the middle way.").C(StatId.Doctrine, 4).P(PersonalStatId.Health, 1).C(StatId.Reputation, -2)),
                new Choice("마을에 공개 사과합니다\u001FPublicly apologize to the village", 0.60f, new Outcome("솔직한 사과에 몇몇 마을 사람들이 누그러집니다.\u001FYour honest apology softens some villagers.").C(StatId.Communion, 3).P(PersonalStatId.Charity, 1).C(StatId.Authority, -2),
                    new Outcome("사과는 오히려 약점 고백으로 받아들여집니다.\u001FThe apology is taken as a confession of weakness.").C(StatId.Reputation, -2).C(StatId.Authority, -3)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_temperance10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10b")) > 0, new Question("가뭄으로 식량이 귀해지자, 평소 신도들을 비웃던 이웃들이 '적게 먹고도 사는 법'을 은근히 묻기 시작합니다.\u001FAs drought makes food scarce, neighbors who used to mock your followers quietly start asking how to 'live on little.'",
                new Choice("공개 강좌를 엽니다\u001FOpen a public class", 0.65f, new Outcome("비웃던 이웃들이 하나둘 강좌 맨 뒷줄에 앉습니다. 밖에서는 여전히 바보들의 모임이라 수군댑니다.\u001FOne by one, the once-mocking neighbors take seats in the back row, while outside people still whisper of a club for fools.").C(StatId.Followers, 6).P(PersonalStatId.Temperance, 1).P(PersonalStatId.Piety, 1),
                    new Outcome("영주의 첩자가 와서 강좌를 '선동'이라 보고합니다.\u001FThe lord's spy reports the class as 'sedition.'").C(StatId.Reputation, -1)).With(PersonalStatId.Integrity),
                new Choice("조용히 신도들 집에서만 가르칩니다\u001FTeach quietly, only in followers' homes", new Outcome("작은 모임마다 등불 같은 이야기가 오갑니다.\u001FStories pass like lamplight through each small gathering.").C(StatId.Communion, 4).C(StatId.Followers, 2)))),
        CultEvent.Conditional("mf_temperance10b_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("temperance10b")) > 0, new Question("눈먼 노파가 '당신 목소리는 등불 같다'며 매일 사원 계단에서 설법을 기다립니다. 사람들은 노망이라 비웃습니다.\u001FA blind old woman waits on the temple steps every day, saying 'your voice is like a lamp.' People laugh it off as senility.",
                new Choice("그녀를 위해 계단에서 설법합니다\u001FPreach to her on the steps", new Outcome("행인들이 비웃다가도 걸음을 늦춥니다.\u001FPassersby sneer, yet slow their steps.").P(PersonalStatId.Piety, 3).P(PersonalStatId.Charity, 2).C(StatId.Reputation, -1)),
                new Choice("그녀를 수행 공동체에 들입니다\u001FWelcome her into the community", 0.70f, new Outcome("노파는 신도들의 이야기 상대가 되어 공동체를 밝힙니다.\u001FShe becomes everyone's companion and brightens the community.").C(StatId.Communion, 5).C(StatId.Offerings, -3),
                    new Outcome("그녀를 돌보는 일이 버겁다며 신도들이 불평합니다.\u001FFollowers complain that caring for her is too much.").C(StatId.Offerings, -4).C(StatId.FollowerFaith, -2)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_charity10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10a")) > 0, new Question("거리의 아이들이 '성자 놀이'를 하며 당신을 흉내 냅니다. 빵을 나눠 주는 시늉 뒤엔 언제나 '바보!' 하는 외침이 따릅니다.\u001FStreet children play 'saint,' imitating you. Every pretend handout of bread ends with a shout of 'Fool!'",
                new Choice("아이들에게 진짜 빵을 나눕니다\u001FGive the children real bread", new Outcome("아이들은 웃으며 빵을 받고, 그날은 '바보'라 외치지 않습니다.\u001FThe children take the bread smiling, and that day nobody shouts 'fool.'").P(PersonalStatId.Charity, 3).P(PersonalStatId.Piety, 1).C(StatId.Offerings, -3)),
                new Choice("놀이에 끼어 함께 웃습니다\u001FJoin the game and laugh along", 0.70f, new Outcome("당신이 스스로 바보 역을 하자 거리가 웃음으로 가득합니다.\u001FWhen you play the fool yourself, the street fills with laughter.").C(StatId.Communion, 3).P(PersonalStatId.Mentality, 2),
                    new Outcome("신도들이 교주의 체통을 걱정합니다.\u001FFollowers fret about their leader's dignity.").C(StatId.Authority, -4)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_charity10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10a")) > 0, new Question("고리대금업자가 당신의 신도들을 '빚을 탕감해 주는 위험 분자'로 고발합니다. 당신들이 가난한 이들의 빚을 대신 갚아 왔기 때문입니다.\u001FA moneylender denounces your followers as 'dangerous debt-forgivers,' because you have been paying off the poor's debts.",
                new Choice("법정에서 당당히 자애를 변호합니다\u001FDefend charity proudly in court", 0.50f, new Outcome("판관이 할 말을 잃고, 방청석 한쪽에서 박수가 터집니다.\u001FThe judge is lost for words, and applause breaks out in one corner of the gallery.").C(StatId.Authority, 4).C(StatId.LeaderFaith, 3).P(PersonalStatId.Charity, 1),
                    new Outcome("벌금이 부과되고, 고리대금업자는 승리의 미소를 짓습니다.\u001FA fine is imposed, and the moneylender grins in triumph.").C(StatId.Offerings, -8).C(StatId.Reputation, -2)).With(PersonalStatId.Integrity),
                new Choice("조용히 벌금을 내고 계속합니다\u001FQuietly pay the fine and continue", new Outcome("신도들은 손해를 보고도 멈추지 않는 당신을 따릅니다.\u001FYour followers stand by a leader who will not stop, even at a loss.").C(StatId.Offerings, -6).P(PersonalStatId.Charity, 3).C(StatId.FollowerFaith, 3)))),
        CultEvent.Conditional("mf_charity10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10a")) > 0, new Question("탐욕으로 이름난 귀족의 딸이 몰래 사원을 찾아와 '착하게 살고 싶다'고 고백합니다. 들키면 그녀는 상속에서 쫓겨납니다.\u001FThe daughter of a notoriously greedy noble secretly visits and confesses she 'wants to live kindly.' If found out, she will be disinherited.",
                new Choice("비밀리에 그녀를 가르칩니다\u001FTeach her in secret", 0.65f, new Outcome("그녀는 아버지 몰래 굶주린 이들에게 곡식을 흘려보냅니다.\u001FBehind her father's back, she channels grain to the hungry.").C(StatId.Followers, 2).C(StatId.Doctrine, 3).P(PersonalStatId.Charity, 2),
                    new Outcome("귀족이 눈치채고 교단에 압력을 넣습니다.\u001FThe noble finds out and pressures the cult.").C(StatId.Authority, -4).C(StatId.Reputation, -2)).With(PersonalStatId.Integrity),
                new Choice("집으로 돌아가 그 자리에서 선을 행하라 권합니다\u001FUrge her to do good where she is", new Outcome("그녀는 고개를 끄덕이고, 저택 안에서 작은 선을 시작합니다.\u001FShe nods and begins small kindnesses inside the manor.").P(PersonalStatId.Piety, 2).P(PersonalStatId.Mentality, 1)))),
        CultEvent.Conditional("mf_charity10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10a")) > 0, new Question("성자의 교단이라는 소문을 듣고 사기꾼 무리가 신도인 척 들어와 구호품을 빼돌립니다.\u001FHearing of a 'cult of saints,' a band of swindlers poses as followers and siphons off relief supplies.",
                new Choice("알고도 용서하며 품습니다\u001FForgive and embrace them knowingly", 0.45f, new Outcome("한 사기꾼이 울며 훔친 것을 돌려놓고 진짜 신도가 됩니다.\u001FOne swindler weeps, returns what he stole, and truly joins.").C(StatId.Followers, 4).P(PersonalStatId.Charity, 4).C(StatId.FollowerFaith, 3),
                    new Outcome("사기꾼들은 더 훔쳐 달아나고, 세상은 '역시 바보들'이라 웃습니다.\u001FThey steal more and flee, and the world laughs, 'Fools, as expected.'").C(StatId.Offerings, -8).C(StatId.Reputation, -1)).With(PersonalStatId.Integrity),
                new Choice("정중히 내보냅니다\u001FPolitely send them away", new Outcome("구호품은 지켰지만 공동체에 서늘한 의심이 남습니다.\u001FThe supplies are saved, but a chill of suspicion lingers.").C(StatId.Offerings, 3).C(StatId.Communion, -1)))),
        CultEvent.Conditional("mf_charity10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10a")) > 0, new Question("홍수 뒤 영주의 곳간은 잠겼고, 당신의 사원만이 문을 열어 이재민을 받습니다. 영주는 '인기 영합'이라며 불쾌해합니다.\u001FAfter a flood, the lord's granary stays locked; only your temple opens its doors to the displaced. The lord calls it 'pandering.'",
                new Choice("모든 이재민을 받아들입니다\u001FTake in every refugee", new Outcome("세상은 여전히 바보짓이라 했지만, 목숨을 건진 이들이 신도가 되었습니다.\u001FThe world still called it folly, but those you saved became followers.").C(StatId.Followers, 5).P(PersonalStatId.Charity, 2).C(StatId.Offerings, -8).C(StatId.Authority, -2)),
                new Choice("영주에게 곳간을 열라고 직언합니다\u001FTell the lord plainly to open his granary", 0.35f, new Outcome("영주가 체면 때문에 마지못해 곳간을 엽니다.\u001FTo save face, the lord reluctantly opens the granary.").C(StatId.Authority, 5).C(StatId.LeaderFaith, 3),
                    new Outcome("영주의 병사들이 당신을 문밖으로 내던집니다.\u001FThe lord's soldiers throw you out the door.").C(StatId.Authority, -6).P(PersonalStatId.Health, -3)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_charity10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10b")) > 0, new Question("사원 앞 환자 줄이 시장 입구까지 이어지자, 상인 조합이 '장사에 방해된다'며 줄을 치우라 요구합니다.\u001FThe line of patients outside the temple stretches to the market gate, and the merchants' guild demands it be cleared as 'bad for business.'",
                new Choice("뒷골목으로 줄을 옮깁니다\u001FMove the line to the back alleys", new Outcome("환자들은 좁은 골목에서도 차례를 지킵니다.\u001FEven in the narrow alley, the patients keep their turn.").C(StatId.Communion, 2).P(PersonalStatId.Charity, 1)),
                new Choice("조합장을 직접 치료해 줍니다\u001FPersonally treat the guild master", 0.55f, new Outcome("오래된 통풍이 나은 조합장이 줄을 그냥 두라고 합니다.\u001FHis old gout eased, the guild master lets the line stay.").C(StatId.Offerings, 5).C(StatId.Authority, 2),
                    new Outcome("조합장은 치료를 받고도 '사기 의술'이라 떠듭니다.\u001FEven after treatment, he babbles about 'quack medicine.'").C(StatId.Reputation, -3).P(PersonalStatId.Health, -2)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_charity10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10b")) > 0, new Question("당신이 고친 탕아가 다시 방탕해져 '사원의 약은 쾌락을 늘려 준다'고 떠벌립니다. 엉뚱한 손님들이 몰려옵니다.\u001FA rake you healed relapses and boasts that 'the temple's medicine boosts pleasure.' The wrong kind of visitors flock in.",
                new Choice("그들도 치료하며 절제를 권합니다\u001FTreat them too, and counsel temperance", 0.60f, new Outcome("쾌락을 찾아온 이들 중 몇몇이 다른 것을 얻고 갑니다.\u001FSome who came for pleasure leave with something else.").C(StatId.Followers, 4).P(PersonalStatId.Temperance, 2).C(StatId.Offerings, 3),
                    new Outcome("소문은 더 추해지고 진짜 환자들이 발길을 돌립니다.\u001FThe rumors grow uglier, and real patients stay away.").C(StatId.Reputation, -2).C(StatId.Offerings, -3)).With(PersonalStatId.Integrity),
                new Choice("소문을 공개적으로 부인합니다\u001FPublicly deny the rumor", new Outcome("소문은 가라앉지만 몇몇 '손님'은 실망해 떠납니다.\u001FThe rumor fades, though a few disappointed 'customers' leave.").P(PersonalStatId.Integrity, 1).P(PersonalStatId.Mentality, 1).C(StatId.Followers, -1)))),
        CultEvent.Conditional("mf_charity10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10b")) > 0, new Question("의사 길드가 '무면허 치료'를 이유로 사원을 고발하고, 동시에 자기들의 비싼 진료비를 올립니다.\u001FThe physicians' guild sues the temple for 'unlicensed healing' while raising their own steep fees.",
                new Choice("무료 진료를 계속합니다\u001FKeep treating for free", new Outcome("가난한 이들은 길드 대신 당신의 줄에 섭니다.\u001FThe poor stand in your line instead of the guild's.").P(PersonalStatId.Charity, 3).C(StatId.Followers, 3).C(StatId.Authority, -3)),
                new Choice("길드 의사에게 함께 일하자 제안합니다\u001FInvite a guild physician to work with you", 0.40f, new Outcome("젊은 의사 하나가 몰래 사원으로 와서 손을 보탭니다.\u001FA young physician slips into the temple to lend a hand.").C(StatId.Authority, 4).C(StatId.Doctrine, 3),
                    new Outcome("제안은 길드 회의에서 공개적으로 조롱당합니다.\u001FThe offer is publicly ridiculed at the guild meeting.").C(StatId.Reputation, -5)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_charity10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10b")) > 0, new Question("밤새 환자를 돌보던 당신이 열병에 걸렸습니다. 세상은 '남 고치다 제 몸 망친 바보'라 비웃습니다.\u001FAfter nursing patients night after night, you catch a fever. The world sneers at 'the fool who ruined himself healing others.'",
                new Choice("앓는 몸으로 계속 돌봅니다\u001FKeep caring while sick", 0.50f, new Outcome("신도들이 당신을 보고 교대로 밤을 지키기 시작합니다.\u001FSeeing you, the followers start keeping watch in shifts.").P(PersonalStatId.Charity, 4).C(StatId.FollowerFaith, 6).P(PersonalStatId.Health, -4),
                    new Outcome("당신은 환자들 사이에서 쓰러집니다.\u001FYou collapse among the patients.").P(PersonalStatId.Health, -8).P(PersonalStatId.Mentality, -3)).With(PersonalStatId.Integrity),
                new Choice("신도들에게 맡기고 쉽니다\u001FRest and entrust it to the followers", new Outcome("신도들이 처음으로 스스로 사원을 꾸려 갑니다.\u001FFor the first time, the followers run the temple on their own.").P(PersonalStatId.Health, 5).C(StatId.Communion, 3)))),
        CultEvent.Conditional("mf_charity10b_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("charity10b")) > 0, new Question("당신이 살린 사형 집행인이 이제는 사람을 죽일 수 없다며 직을 내려놓고 찾아옵니다. 영주는 분노합니다.\u001FAn executioner you once saved resigns, saying he can no longer kill, and comes to you. The lord is furious.",
                new Choice("그를 사원의 일꾼으로 받습니다\u001FAccept him as a temple worker", 0.60f, new Outcome("가장 거친 손이 가장 부드럽게 환자를 붕대로 감습니다.\u001FThe roughest hands now bind wounds most gently.").C(StatId.Followers, 2).C(StatId.Communion, 4).P(PersonalStatId.Piety, 2),
                    new Outcome("영주가 사원에 세금을 두 배로 매깁니다.\u001FThe lord doubles the temple's taxes.").C(StatId.Authority, -6)).With(PersonalStatId.Integrity),
                new Choice("영주와 화해하라 돌려보냅니다\u001FSend him back to make peace with the lord", new Outcome("신도들은 말없이 그의 뒷모습을 봅니다.\u001FThe followers silently watch him go.").C(StatId.Authority, 2).C(StatId.FollowerFaith, -2)))),
        CultEvent.Conditional("mf_patience10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10a")) > 0, new Question("교단 사원이 원인 모를 불로 반쯤 탔습니다. 이웃들은 잿더미 앞에서 '하늘도 바보들을 미워한다'고 웃습니다.\u001FThe temple half-burns in a fire of unknown origin. Neighbors laugh over the ashes: 'Even heaven hates fools.'",
                new Choice("맨손으로 재건을 시작합니다\u001FStart rebuilding with your bare hands", new Outcome("신도들이 하나둘 벽돌을 나르며 합류합니다.\u001FOne by one, followers join you hauling bricks.").C(StatId.FollowerFaith, 5).P(PersonalStatId.Patience, 2).P(PersonalStatId.Health, -3)),
                new Choice("잿더미 위에서 예배를 엽니다\u001FHold a service on the ashes", 0.65f, new Outcome("비웃던 이웃 몇이 잿더미 가장자리에서 고개를 숙입니다.\u001FA few mocking neighbors bow their heads at the edge of the ashes.").C(StatId.Communion, 5).P(PersonalStatId.Piety, 2),
                    new Outcome("예배는 구경거리가 되고, 몇 신도는 부끄러워합니다.\u001FThe service becomes a spectacle, and some followers feel ashamed.").C(StatId.Reputation, -2).C(StatId.FollowerFaith, -2)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_patience10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10a")) > 0, new Question("감옥에 갇힌 신도가 배교하면 풀어 주겠다는 제안을 받았습니다. 그의 어머니가 당신에게 매달립니다.\u001FAn imprisoned follower is offered freedom if he renounces the faith. His mother clings to you, begging.",
                new Choice("살아남으라고, 배교해도 좋다고 전합니다\u001FTell him to survive, even if he must renounce", new Outcome("그는 풀려나 몰래 다시 예배에 나옵니다.\u001FHe is released and secretly returns to worship.").P(PersonalStatId.Charity, 2).C(StatId.FollowerFaith, -2).P(PersonalStatId.Mentality, 2)),
                new Choice("함께 감옥에 들어가 곁을 지킵니다\u001FEnter the prison to stay by his side", 0.45f, new Outcome("간수들이 당신들의 노래에 감화되어 형기가 줄어듭니다.\u001FMoved by your songs, the guards shorten the sentence.").C(StatId.FollowerFaith, 8).C(StatId.LeaderFaith, 4).P(PersonalStatId.Patience, 3),
                    new Outcome("당신은 매를 맞고 아무것도 얻지 못한 채 나옵니다.\u001FYou are beaten and come out with nothing.").P(PersonalStatId.Health, -6).C(StatId.Authority, -4)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_patience10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10a")) > 0, new Question("순교자의 무덤에 꽃이 끊이지 않자, 영주는 무덤을 파헤치라 명합니다.\u001FFlowers never stop appearing at a martyr's grave, so the lord orders it dug up.",
                new Choice("밤에 유해를 몰래 옮깁니다\u001FSecretly move the remains at night", 0.60f, new Outcome("새 무덤의 위치는 신도들만의 비밀이 됩니다.\u001FThe new grave becomes a secret only the followers share.").C(StatId.Communion, 5).P(PersonalStatId.Piety, 2),
                    new Outcome("발각되어 신도 둘이 붙잡힙니다.\u001FYou are discovered, and two followers are seized.").C(StatId.Authority, -4).C(StatId.Followers, -2)).With(PersonalStatId.Integrity),
                new Choice("무덤 앞에 앉아 길을 막습니다\u001FSit before the grave and block the way", 0.50f, new Outcome("병사들이 차마 노인을 끌어내지 못하고 물러납니다.\u001FThe soldiers cannot bring themselves to drag you off, and withdraw.").C(StatId.Authority, 3).C(StatId.FollowerFaith, 4).P(PersonalStatId.Patience, 2),
                    new Outcome("당신은 끌려 나가고 무덤은 파헤쳐집니다.\u001FYou are dragged away and the grave is dug up.").P(PersonalStatId.Health, -5).C(StatId.Reputation, -1)).With(PersonalStatId.Integrity),
                new Choice("무덤 대신 마음에 새기라고 설법합니다\u001FPreach that memory needs no grave", new Outcome("신도들은 슬퍼하지만 가르침을 받아들입니다.\u001FThe followers grieve but accept the teaching.").C(StatId.Doctrine, 4).C(StatId.FollowerFaith, -1)))),
        CultEvent.Conditional("mf_patience10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10a")) > 0, new Question("10년째 당신을 비웃어 온 술집 주인이 파산해 거리에 나앉았습니다. 그가 사원 문 앞에서 머뭇거립니다.\u001FThe tavern keeper who mocked you for ten years has gone bankrupt and lives on the street. He hesitates at the temple door.",
                new Choice("먼저 다가가 문을 엽니다\u001FGo to him and open the door", new Outcome("그는 말없이 들어와 오래 웁니다.\u001FHe walks in without a word and weeps for a long time.").C(StatId.Followers, 1).P(PersonalStatId.Charity, 2).C(StatId.Communion, 2)),
                new Choice("신도들에게 그를 맞을지 묻습니다\u001FAsk the followers whether to take him in", 0.60f, new Outcome("오래 고민한 신도들이 그를 받아들이기로 합니다.\u001FAfter long deliberation, the followers decide to accept him.").C(StatId.Communion, 5).C(StatId.Doctrine, 2),
                    new Outcome("신도들이 분열해 언성을 높이고 그는 떠나 버립니다.\u001FThe followers split and argue, and he walks away.").C(StatId.Communion, -3).P(PersonalStatId.Mentality, -2)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_patience10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10a")) > 0, new Question("흉년과 역병이 겹쳐 신도 수가 절반으로 줄었습니다. 남은 이들이 '그래도 계속하느냐'고 묻습니다.\u001FFamine and plague together have halved the followers. Those remaining ask, 'Do we still go on?'",
                new Choice("작아도 계속한다고 답합니다\u001FAnswer that you go on, however small", new Outcome("남은 신도들의 눈빛이 더 단단해집니다.\u001FThe remaining followers' eyes grow firmer.").C(StatId.FollowerFaith, 6).P(PersonalStatId.Patience, 2).C(StatId.Followers, -1)),
                new Choice("떠날 자유를 공개적으로 줍니다\u001FOpenly grant them freedom to leave", 0.55f, new Outcome("아무도 떠나지 않고, 공동체는 오히려 결속됩니다.\u001FNo one leaves, and the community grows tighter.").C(StatId.Communion, 6).P(PersonalStatId.Integrity, 2),
                    new Outcome("몇몇이 미안해하며 떠나고, 남은 이들은 더 가까워집니다.\u001FA few leave apologetically, and the rest draw closer.").C(StatId.Followers, -5).C(StatId.Communion, 2)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_patience10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10b")) > 0, new Question("당신의 순례 행렬이 영주의 병사들에게 다리 앞에서 막혔습니다. 병사들은 '돌아가라, 바보들'이라 외칩니다.\u001FYour pilgrim procession is blocked at a bridge by the lord's soldiers, who shout, 'Go back, fools!'",
                new Choice("다리 앞에 앉아 사흘을 기다립니다\u001FSit before the bridge and wait three days", 0.55f, new Outcome("사흘째 아침, 병사들이 말없이 길을 비킵니다.\u001FOn the third morning, the soldiers silently step aside.").C(StatId.Authority, 3).P(PersonalStatId.Patience, 3).C(StatId.FollowerFaith, 3).C(StatId.Reputation, 2),
                    new Outcome("병사들은 끄떡없고, 지친 신도 몇이 흩어집니다.\u001FThe soldiers don't budge, and a few exhausted followers scatter.").P(PersonalStatId.Health, -4).C(StatId.Followers, -3)).With(PersonalStatId.Integrity),
                new Choice("먼 길로 돌아갑니다\u001FTake the long way around", new Outcome("긴 우회 끝에 행렬은 한층 단단해집니다.\u001FAfter the long detour, the procession is stronger for it.").P(PersonalStatId.Health, -2).C(StatId.Communion, 3)))),
        CultEvent.Conditional("mf_patience10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10b")) > 0, new Question("행렬이 지나는 마을마다 아이들이 돌을 던지지만, 한 마을에서는 노인이 물동이를 들고 나옵니다.\u001FIn every village along the route children throw stones, but in one village an old man comes out with a water jar.",
                new Choice("행렬을 멈추고 그 마을에 머뭅니다\u001FHalt and stay in that village", 0.65f, new Outcome("노인의 집을 중심으로 작은 모임이 생깁니다.\u001FA small gathering forms around the old man's home.").C(StatId.Followers, 5).C(StatId.Communion, 2),
                    new Outcome("촌장이 노인을 꾸짖고 당신들을 쫓아냅니다.\u001FThe headman scolds the old man and drives you out.").C(StatId.Reputation, -3).C(StatId.Offerings, -3)).With(PersonalStatId.Integrity),
                new Choice("물만 받고 감사히 지나갑니다\u001FAccept the water gratefully and move on", new Outcome("노인은 행렬이 사라질 때까지 손을 흔듭니다.\u001FThe old man waves until the procession is out of sight.").C(StatId.FollowerFaith, 3).P(PersonalStatId.Piety, 2).C(StatId.Reputation, 2)))),
        CultEvent.Conditional("mf_patience10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10b")) > 0, new Question("화려한 욕망 축제 행렬이 맞은편에서 다가옵니다. 길이 좁아 한쪽이 비켜야 합니다.\u001FA lavish festival procession of desire approaches from the other side. The road is narrow; one must give way.",
                new Choice("묵묵히 서서 기다립니다\u001FStand silently and wait", 0.50f, new Outcome("축제 행렬이 머쓱해져 먼저 길가로 비킵니다.\u001FAbashed, the festival procession steps aside first.").C(StatId.Authority, 4).C(StatId.LeaderFaith, 3),
                    new Outcome("축제 인파가 밀고 지나가며 신도들이 넘어집니다.\u001FThe festival crowd shoves through, knocking followers down.").C(StatId.Reputation, -5).P(PersonalStatId.Health, -2)).With(PersonalStatId.Integrity),
                new Choice("먼저 비켜 주며 축복합니다\u001FGive way first and bless them", new Outcome("축제객 몇이 어리둥절한 얼굴로 축복을 받습니다.\u001FA few revelers receive the blessing with puzzled faces.").P(PersonalStatId.Charity, 2).C(StatId.Communion, 2)))),
        CultEvent.Conditional("mf_patience10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10b")) > 0, new Question("폭설 속 행렬에서 늙은 신도가 더 걸을 수 없다고 주저앉습니다.\u001FIn a blizzard, an elderly follower sinks down, saying he can walk no further.",
                new Choice("직접 그를 업고 걷습니다\u001FCarry him on your back", 0.60f, new Outcome("교주의 등을 본 신도들이 서로를 부축하며 눈길을 뚫습니다.\u001FSeeing your back, the followers help one another through the snow.").C(StatId.FollowerFaith, 6).P(PersonalStatId.Patience, 2).P(PersonalStatId.Health, -4).C(StatId.Reputation, 2),
                    new Outcome("당신도 눈 속에 쓰러져 행렬이 하루 멈춥니다.\u001FYou collapse in the snow too, and the procession halts a day.").P(PersonalStatId.Health, -7)).With(PersonalStatId.Integrity),
                new Choice("행렬 전체가 그곳에 야영합니다\u001FHave the whole procession camp there", new Outcome("눈보라 속 모닥불 곁에서 노래가 이어집니다.\u001FSongs carry on around the campfire in the storm.").C(StatId.Communion, 4).C(StatId.Offerings, -3)))),
        CultEvent.Conditional("mf_patience10b_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("patience10b")) > 0, new Question("수년간 이어진 당신의 순례를 기록하던 풍자 작가가, 마지막 장에서 행렬을 조롱할 수 없었다고 고백합니다.\u001FA satirist who chronicled your pilgrimages for years confesses he could not mock the procession in the final chapter.",
                new Choice("그의 책 출간을 돕습니다\u001FHelp publish his book", 0.55f, new Outcome("책은 비웃음 섞인 경탄 속에 읽히고, 몇몇 독자가 행렬을 찾아옵니다.\u001FThe book is read with mocking admiration, and a few readers come to find the procession.").C(StatId.Doctrine, 4).C(StatId.Followers, 3).C(StatId.Offerings, -3),
                    new Outcome("출판사는 '팔리지 않을 이야기'라며 거절합니다.\u001FPublishers refuse it as 'a story that won't sell.'").C(StatId.Offerings, -4).C(StatId.Reputation, -2)).With(PersonalStatId.Integrity),
                new Choice("그에게 행렬에 함께 걷자고 권합니다\u001FInvite him to walk with the procession", new Outcome("그는 펜을 내려놓고 지팡이를 듭니다.\u001FHe sets down his pen and takes up a staff.").C(StatId.Followers, 1).C(StatId.Communion, 3)))),
        CultEvent.Conditional("mf_integrity10a_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10a")) > 0, new Question("교단의 모든 장부를 광장에 공개하자, 사람들은 '감출 게 없다니 정말 바보로군'이라며 장부를 넘겨봅니다.\u001FWhen you display all the cult's ledgers in the square, people flip through saying, 'Nothing to hide? A true fool.'",
                new Choice("질문 하나하나에 답합니다\u001FAnswer every single question", new Outcome("지친 끝에, 의심하던 이들이 하나둘 고개를 끄덕입니다.\u001FBy the end you are exhausted, but doubters begin to nod.").P(PersonalStatId.Integrity, 3).C(StatId.FollowerFaith, 3).P(PersonalStatId.Mentality, -2)),
                new Choice("장부를 매달 공개하기로 정합니다\u001FMake monthly disclosure a rule", 0.65f, new Outcome("정직한 장부는 교단의 상징이 됩니다.\u001FThe honest ledger becomes the cult's emblem.").C(StatId.Doctrine, 4).C(StatId.Authority, 3),
                    new Outcome("상인들이 헌금 흐름을 보고 '돈이 안 되는 곳'이라 소문냅니다.\u001FMerchants read the flows and spread word it's 'unprofitable.'").C(StatId.Offerings, -4)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_integrity10a_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10a")) > 0, new Question("당신의 측근이 몰래 영주에게 뇌물을 바쳐 탄압을 피해 왔다는 사실이 드러났습니다.\u001FIt comes out that your close aide has been secretly bribing the lord to avoid persecution.",
                new Choice("공개적으로 사실을 밝히고 사과합니다\u001FReveal it publicly and apologize", 0.60f, new Outcome("신도들은 상처 입었지만 당신의 정직을 믿습니다.\u001FHurt, the followers still trust your honesty.").P(PersonalStatId.Integrity, 3).C(StatId.FollowerFaith, 4).C(StatId.Authority, -3),
                    new Outcome("영주가 뇌물을 끊긴 데 앙심을 품습니다.\u001FThe lord resents the end of the bribes.").C(StatId.Authority, -6).C(StatId.Reputation, -1)).With(PersonalStatId.Integrity),
                new Choice("측근을 조용히 내보냅니다\u001FQuietly dismiss the aide", new Outcome("공동체에 말 못 할 서운함이 남습니다.\u001FAn unspoken sorrow lingers in the community.").P(PersonalStatId.Integrity, 1).C(StatId.Communion, -2)))),
        CultEvent.Conditional("mf_integrity10a_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10a")) > 0, new Question("거짓말이 미덕인 세상에서, 법정 증인들이 모두 위증합니다. 당신만이 진실을 알지만 말하면 친한 상인이 망합니다.\u001FIn a world where lying is a virtue, every witness in court perjures. Only you know the truth, but telling it will ruin a merchant friend.",
                new Choice("진실을 증언합니다\u001FTestify to the truth", new Outcome("판결이 뒤집히고, 친구는 등을 돌립니다.\u001FThe verdict is overturned, and your friend turns his back.").P(PersonalStatId.Integrity, 4).C(StatId.Reputation, -2).P(PersonalStatId.Piety, 2)),
                new Choice("침묵하되 거짓은 말하지 않습니다\u001FStay silent but tell no lie", 0.70f, new Outcome("판관은 당신의 침묵에서 무언가를 읽어 냅니다.\u001FThe judge reads something in your silence.").P(PersonalStatId.Mentality, 2).P(PersonalStatId.Piety, 1),
                    new Outcome("침묵도 공모였다는 생각이 오래 당신을 괴롭힙니다.\u001FThe thought that silence was complicity torments you.").P(PersonalStatId.Integrity, -2).P(PersonalStatId.Mentality, -3)).With(PersonalStatId.Integrity))),
        CultEvent.Conditional("mf_integrity10a_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10a")) > 0, new Question("한 첩자가 교단의 비밀을 캐려 잠입했지만, 캘 비밀이 없어 보고서를 쓰지 못하고 있습니다.\u001FA spy infiltrates the cult to dig up secrets, but finding none, he cannot write his report.",
                new Choice("그를 알고도 환대합니다\u001FWelcome him, knowing who he is", 0.55f, new Outcome("그의 보고서는 '위험 없음, 다만 지나치게 정직함'이 됩니다.\u001FHis report reads: 'No danger, only excessive honesty.'").C(StatId.Followers, 2).C(StatId.Authority, 3),
                    new Outcome("그는 없는 비밀을 지어내 보고합니다.\u001FHe fabricates secrets for his report.").C(StatId.Authority, -4)).With(PersonalStatId.Integrity),
