        CultEvent.Conditional("mf_integrity10a_5", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10a")) > 0, new Question("가면 무도회가 유행인 도시에서, 신도들은 맨얼굴로 다니는 것이 규율입니다. 시의회가 '불쾌하다'며 가면 착용을 명합니다.\u001FIn a city mad for masquerades, your followers' rule is to go bare-faced. The council orders masks, calling it 'offensive.'",
                new Choice("맨얼굴을 고수합니다\u001FHold to bare faces", 0.50f, new Outcome("몇몇 시민이 가면을 벗고 행렬에 섞입니다.\u001FSome citizens remove their masks and join you.").C(StatId.FollowerFaith, 5).P(PersonalStatId.Integrity, 2).C(StatId.LeaderFaith, 3),
                    new Outcome("신도 몇이 벌금을 물고 연행됩니다.\u001FSeveral followers are fined and detained.").C(StatId.Authority, -5).C(StatId.Followers, -2)).With(PersonalStatId.Integrity),
                new Choice("투명한 유리 가면을 만듭니다\u001FCraft clear glass masks", new Outcome("법도 지키고 얼굴도 숨기지 않는 가면이 화제가 됩니다.\u001FMasks that obey the law yet hide nothing become the talk of the town.").C(StatId.Doctrine, 3).C(StatId.Communion, 2)))),
        CultEvent.Conditional("mf_integrity10b_1", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10b")) > 0, new Question("시장에서 저울 눈금을 속이는 것이 당연한 관습입니다. 당신의 신도 상인만 정확한 저울을 써서 '장사 못 하는 바보'라 불립니다.\u001FRigging scales is normal practice in the market. Only your follower merchant uses honest weights and is called 'a fool who can't trade.'",
                new Choice("정직한 저울을 교단 표식으로 삼습니다\u001FMake the honest scale the cult's mark", 0.60f, new Outcome("정확한 무게를 원하는 손님들이 그 가게로 몰립니다.\u001FCustomers who want true weight crowd into his shop.").C(StatId.Doctrine, 4).C(StatId.Followers, 3).P(PersonalStatId.Integrity, 1),
                    new Outcome("다른 상인들이 담합해 그 가게를 고립시킵니다.\u001FOther merchants collude to isolate the shop.").C(StatId.Offerings, -4).C(StatId.Reputation, -1)).With(PersonalStatId.Integrity),
                new Choice("상인의 손실을 교단이 메워 줍니다\u001FHave the cult cover his losses", new Outcome("상인은 눈물을 글썽이며 저울을 지킵니다.\u001FTeary-eyed, the merchant keeps his honest scale.").C(StatId.Offerings, -5).P(PersonalStatId.Integrity, 2).C(StatId.FollowerFaith, 3)))),
        CultEvent.Conditional("mf_integrity10b_2", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10b")) > 0, new Question("영주가 법을 비웃듯 마음대로 바꾸는 동안, 당신의 교단만은 50년 된 계율을 한 글자도 고치지 않습니다. 젊은 신도가 시대에 맞추자고 합니다.\u001FWhile the lord rewrites laws at whim, your cult hasn't changed a letter of its fifty-year-old precepts. A young follower urges updating them.",
                new Choice("계율은 그대로 지킵니다\u001FKeep the precepts as they are", new Outcome("젊은 신도는 투덜대지만 계율의 무게를 느낍니다.\u001FThe young follower grumbles but feels the precepts' weight.").C(StatId.Authority, 4).C(StatId.Doctrine, 2).C(StatId.Communion, -2)),
                new Choice("해석을 함께 토론합니다\u001FDebate the interpretation together", 0.65f, new Outcome("글자는 그대로 두되, 뜻이 새로워집니다.\u001FThe letters stay, but their meaning is renewed.").C(StatId.Communion, 5).C(StatId.Doctrine, 3),
