        CultEvent.Conditional("mf_integrity10b_3", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10b")) > 0, new Question("부패한 판관이 당신에게 교단의 계율로 마을 분쟁을 중재해 달라고 비꼬듯 청합니다. 실패하면 웃음거리가 됩니다.\u001FA corrupt judge sarcastically asks you to settle a village dispute by your cult's law. Failure will make you a laughingstock.",
                new Choice("공정하게 중재합니다\u001FMediate fairly", 0.50f, new Outcome("양쪽 모두 고개를 숙이고, 판관은 말을 잃습니다.\u001FBoth sides bow, and the judge is speechless.").C(StatId.Authority, 5).P(PersonalStatId.Integrity, 2).C(StatId.LeaderFaith, 3),
                    new Outcome("패한 쪽이 '사교의 재판'이라며 소동을 일으킵니다.\u001FThe losing side riots over 'a cult's trial.'").C(StatId.Reputation, -3)).With(PersonalStatId.Integrity),
                new Choice("판관의 권한이라며 사양합니다\u001FDecline, saying it is the judge's duty", new Outcome("판관은 '겁쟁이'라 비웃지만 함정은 피했습니다.\u001FThe judge sneers 'coward,' but you avoid the trap.").P(PersonalStatId.Integrity, 1).C(StatId.Reputation, -1)))),
        CultEvent.Conditional("mf_integrity10b_4", c => c.Doctrines.LevelOf(MirrorDoctrineCatalog.Find("integrity10b")) > 0, new Question("가난한 신도가 굶주린 자식을 위해 빵을 훔쳤습니다. 계율대로라면 그는 공동체에서 쫓겨나야 합니다.\u001FA poor follower stole bread for his starving child. By the precepts, he must be expelled.",
